#include "beatglass/library/analysis_commit.hpp"
namespace beatglass::library { library_detail::Publish publish_operation(library_detail::SqliteCache& cache,const std::string& id,const AnalysisOperation& op,std::stop_token stop){ if(id.empty()||!op.valid()) return library_detail::Publish::error; auto verifier=[&]{return op.verify(stop).outcome==FileVerificationOutcome::match;}; CacheKey key{op.identity.content_hash,op.identity.engine_version,op.identity.configuration_id,op.identity.mode}; return cache.publish(id,key,op.serialize(),stop,verifier); } }
